         api_battery_assessment.result == AssessmentResult.NoAssessment)

  /** CEP-T-Case: Top-Level case contracts for result_custody's compute entrypoint
    *
    * @param In_publicationState pre-state state variable
    * @param In_retainedAssessment pre-state state variable
