    * @param api_decision_assessment incoming data port
    * @param api_publication_directive incoming data port
    * @param api_battery_assessment outgoing data port
    */
  @strictpure def compute_CEP_T_Case (
      In_publicationState: Battery_Status_Assessment_Service.PublicationState.Type,
      In_retainedAssessment: Battery_Status_Assessment_Service.AssessmentResult.Type,
