      api_publication_directive: Battery_Status_Assessment_Service.PublicationDirective.Type,
      api_battery_assessment: Battery_Status_Assessment_Service.TaggedAssessment): B =
    {
      val r0 = compute_case_PUBLICATION_RESET(committedPublicationOutcome, publicationState, retainedAssessment, api_publication_directive, api_battery_assessment)
      val r1 = compute_case_PUBLICATION_HELD(In_publicationState, committedPublicationOutcome, publicationState, retainedAssessment, api_publication_directive, api_battery_assessment)
      val r2 = compute_case_UNEXPECTED_OPEN_WHILE_OFFERED(In_publicationState, committedPublicationOutcome, publicationState, retainedAssessment, api_control_use_feedback, api_publication_directive, api_battery_assessment)
      val r3 = compute_case_FEEDBACK_FAULT(In_publicationState, committedPublicationOutcome, publicationState, retainedAssessment, api_control_use_feedback, api_publication_directive, api_battery_assessment)
      val r4 = compute_case_CONSUME_TOKEN_A(In_publicationState, committedPublicationOutcome, publicationState, retainedAssessment, api_control_use_feedback, api_publication_directive, api_battery_assessment)
      val r5 = compute_case_CONSUME_TOKEN_B(In_publicationState, committedPublicationOutcome, publicationState, retainedAssessment, api_control_use_feedback, api_publication_directive, api_battery_assessment)
      val r6 = compute_case_WITHDRAW_COHERENT_OFFER(In_publicationState, committedPublicationOutcome, publicationState, retainedAssessment, api_control_use_feedback, api_publication_directive, api_battery_assessment)
      val r7 = compute_case_PRESERVE_TOKEN_A(In_publicationState, In_retainedAssessment, committedPublicationOutcome, publicationState, retainedAssessment, api_control_use_feedback, api_publication_directive, api_battery_assessment)
      val r8 = compute_case_PRESERVE_TOKEN_B(In_publicationState, In_retainedAssessment, committedPublicationOutcome, publicationState, retainedAssessment, api_control_use_feedback, api_publication_directive, api_battery_assessment)
      val r9 = compute_case_OPEN_TOKEN_A(In_publicationState, committedPublicationOutcome, publicationState, retainedAssessment, api_control_use_feedback, api_decision_assessment, api_publication_directive, api_battery_assessment)
      val r10 = compute_case_OPEN_TOKEN_B(In_publicationState, committedPublicationOutcome, publicationState, retainedAssessment, api_control_use_feedback, api_decision_assessment, api_publication_directive, api_battery_assessment)
      val r11 = compute_case_CUSTODY_INACTIVE(In_publicationState, committedPublicationOutcome, publicationState, retainedAssessment, api_control_use_feedback, api_decision_assessment, api_publication_directive, api_battery_assessment)

      r0 & r1 & r2 & r3 & r4 & r5 & r6 & r7 & r8 & r9 & r10 & r11
    }

  /** CEP-Post: Compute Entrypoint Post-Condition for result_custody
    *
    * @param In_committedPublicationOutcome pre-state state variable
    * @param In_publicationState pre-state state variable
    * @param In_retainedAssessment pre-state state variable
    * @param committedPublicationOutcome post-state state variable
